package scanners

import (
	"strings"
	"testing"
)

// Fixtures of the GitLab security report, IaC and CI/CD import formats
// (testdata/imports).
//
// Generated by running the tool against a small sample (a Terraform file
// with a public S3 bucket and an open SSH security group, a privileged
// Kubernetes Deployment, a CloudFormation template, a Dockerfile and a
// pull_request_target GitHub workflow), then trimmed to a few findings
// (structure kept):
//   - gl-sast.json: GitLab semgrep analyzer 5.32.2
//     (registry.gitlab.com/security-products/semgrep:5) on a Python file;
//   - gl-secret-detection.json: GitLab secrets analyzer 6.28.0 (secrets:6)
//     on fake AWS and GitLab tokens;
//   - gl-dependency-scanning.json: GitLab gemnasium analyzer
//     (gemnasium:5) on a package-lock.json with minimist 1.2.5 and lodash
//     4.17.20;
//   - gl-container-scanning.json: GitLab container scanning 7.5.8
//     (container-scanning:7, Trivy 0.61.0) on alpine:3.14.0;
//   - kics.json: checkmarx/kics v2.2.1 (paths as KICS writes them);
//   - tfsec.json: aquasec/tfsec v1.28.14;
//   - terrascan.json: tenable/terrascan v1.19.9;
//   - kube-linter.json: stackrox/kube-linter 0.8.3;
//   - kubescape.json: quay.io/kubescape/kubescape-cli v3.0.46;
//   - cfn-lint.json: cfn-lint 1.60.1 (pip, python:3.12-slim);
//   - cfn-nag.json: stelligent/cfn_nag 0.8.9;
//   - hadolint.json: hadolint/hadolint 2.15.1;
//   - tflint.json: ghcr.io/terraform-linters/tflint 0.66.0 (bundled
//     terraform ruleset);
//   - conftest.json: openpolicyagent/conftest v0.71.1 with a two-rule Rego
//     policy;
//   - polaris.json: quay.io/fairwinds/polaris 10.1.8 (`polaris audit
//     --audit-path`);
//   - kube-bench.json: aquasec/kube-bench v0.16.0 (`run --targets node`
//     on a host that is not a Kubernetes node);
//   - poutine.json: ghcr.io/boostsecurityio/poutine 1.1.6
//     (`analyze_local`);
//   - scorecard.json: OpenSSF Scorecard v5.7.0 (`scorecard --local`,
//     built with go install in golang:1.27.4).
//
// Built from the published format (no real report available):
// gl-dast.json and gl-coverage-fuzzing.json (GitLab security report schema
// 15; the analyzers need a deployed target or a fuzz target),
// legitify.json (from the Legitify source: outputer/scheme; a real run
// needs a GitHub token).

func TestImportGitLabAndIaCFormats(t *testing.T) {
	runImportCases(t, []importCase{
		{file: "gl-sast.json", format: "gl-sast", count: 2, checks: map[int]want{
			0: {sev: "high", cwe: "CWE-78", file: "app/views.py", line: 6, rule: "bandit.B602"},
			1: {sev: "medium", cwe: "CWE-327", line: 10, rule: "bandit.B303-1"},
		}},
		{file: "gl-secret-detection.json", format: "gl-secret-detection", count: 2, checks: map[int]want{
			0: {sev: "critical", cwe: "CWE-798", file: "config/settings.py", line: 2, rule: "gitlab_personal_access_token"},
			1: {rule: "AWS", line: 1},
		}, secrets: []string{"glpat-FIXTURE.not.real", "AKIAZ7FAKEEXAMPLE7QX"}},
		{file: "gl-dependency-scanning.json", format: "gl-dependency-scanning", count: 2, checks: map[int]want{
			0: {sev: "critical", cve: "CVE-2021-44906", file: "package-lock.json", pkg: "minimist", ver: "1.2.5", fixed: "1.2.6", rule: "CVE-2021-44906"},
			1: {sev: "high", pkg: "lodash", ver: "4.17.20", fixed: "4.18.0"},
		}},
		{file: "gl-container-scanning.json", format: "gl-container-scanning", count: 3, checks: map[int]want{
			0: {sev: "critical", cve: "CVE-2021-36159", file: "alpine:3.14.0", pkg: "apk-tools", ver: "2.12.5-r1", fixed: "2.12.6-r0"},
			2: {sev: "medium", pkg: "libcrypto1.1", fixed: "1.1.1q-r0"},
		}},
		{file: "gl-dast.json", format: "gl-dast", count: 2, checks: map[int]want{
			0: {sev: "high", cwe: "CWE-79", file: "https://app.example/search", rule: "40012"},
			1: {sev: "low", cwe: "CWE-319", file: "https://app.example/"},
		}},
		{file: "gl-coverage-fuzzing.json", format: "gl-coverage-fuzzing", count: 1, checks: map[int]want{
			0: {sev: "medium", rule: "Heap-buffer-overflow READ 1"},
		}},
		{file: "kics.json", format: "kics", count: 3, checks: map[int]want{
			0: {sev: "critical", cwe: "CWE-732", file: "infra/main.tf", line: 3, rule: "38c5ee0d-7f22-4260-ab72-5073048df100"},
			1: {sev: "high", cwe: "CWE-269", file: "k8s/deployment.yaml", line: 19},
			2: {sev: "low", file: "Dockerfile", line: 4},
		}},
		{file: "tfsec.json", format: "tfsec", count: 3, checks: map[int]want{
			0: {sev: "critical", file: "infra/main.tf", line: 12, rule: "AVD-AWS-0107"},
			2: {sev: "low", line: 6, endLine: 14, rule: "AVD-AWS-0099"},
		}},
		{file: "terrascan.json", format: "terrascan", count: 3, checks: map[int]want{
			0: {sev: "medium", file: "Dockerfile", line: 1, rule: "AC_DOCKER_0041"},
			2: {sev: "high", file: "infra/main.tf", line: 6, rule: "AC_AWS_0227"},
		}},
		{file: "kube-linter.json", format: "kube-linter", count: 2, checks: map[int]want{
			0: {sev: "medium", file: "k8s/deployment.yaml", rule: "latest-tag"},
			1: {sev: "high", rule: "privileged-container"},
		}},
		{file: "kubescape.json", format: "kubescape", count: 2, checks: map[int]want{
			0: {sev: "low", file: "deployment.yaml", rule: "C-0061"},
			1: {sev: "high", rule: "C-0057"},
		}},
		{file: "cfn-lint.json", format: "cfn-lint", count: 2, checks: map[int]want{
			0: {sev: "high", file: "template.yaml", line: 5, rule: "E3045"},
			1: {sev: "medium", line: 6, rule: "W3045"},
		}},
		{file: "cfn-nag.json", format: "cfn-nag", count: 3, checks: map[int]want{
			0: {sev: "medium", file: "cfn/template.yaml", line: 4, rule: "W31"},
			1: {sev: "high", line: 8, rule: "F1000"},
		}},
		{file: "hadolint.json", format: "hadolint", count: 7, checks: map[int]want{
			0: {sev: "medium", file: "Dockerfile", line: 1, rule: "DL3007"},
			1: {sev: "info", rule: "DL3009"},
			4: {sev: "high", line: 3, rule: "DL3000"},
		}},
		{file: "tflint.json", format: "tflint", count: 2, checks: map[int]want{
			0: {sev: "medium", file: "infra/main.tf", line: 1, rule: "terraform_required_version"},
		}},
		{file: "conftest.json", format: "conftest", count: 2, checks: map[int]want{
			0: {sev: "high", file: "k8s/deployment.yaml", rule: "data.main.deny"},
			1: {sev: "medium", rule: "data.main.warn"},
		}},
		{file: "polaris.json", format: "polaris", count: 5, checks: map[int]want{
			0: {sev: "medium", rule: "deploymentMissingReplicas"},
			3: {sev: "high", rule: "runAsPrivileged"},
		}, cats: map[int]string{0: "code-quality", 1: "iac", 3: "iac", 4: "code-quality"}},
		{file: "kube-bench.json", format: "kube-bench", count: 3, checks: map[int]want{
			0: {sev: "medium", rule: "CIS 4.1.1"},
			1: {sev: "low", rule: "CIS 4.1.6"},
		}},
		{file: "poutine.json", format: "poutine", count: 3, checks: map[int]want{
			0: {sev: "high", file: ".github/workflows/ci.yml", line: 11, rule: "untrusted_checkout_exec"},
			1: {sev: "medium", line: 10, rule: "injection"},
		}},
		{file: "legitify.json", format: "legitify", count: 2, checks: map[int]want{
			0: {sev: "critical", file: "https://github.com/acme", rule: "data.organization.two_factor_authentication_not_required_for_org"},
			1: {sev: "high", file: "https://github.com/acme/legacy-api"},
		}},
		{file: "scorecard.json", format: "scorecard", count: 3, checks: map[int]want{
			0: {sev: "critical", rule: "Dangerous-Workflow"},
			1: {sev: "medium", rule: "Pinned-Dependencies"},
			2: {sev: "high", rule: "Token-Permissions"},
		}},
	})
}

func TestImportGitLabDetails(t *testing.T) {
	// Aliases share the GitLab parser and set the category of their report
	// type; the generic "gitlab" format keeps each finding's category.
	raw := readImport(t, "gl-dast.json")
	if !SameImportParser("gl-dast", "gitlab") || !SameImportParser("gl-sast", "gl-secret-detection") {
		t.Fatal("aliases share the gitlab parser")
	}
	fs, err := ParseImport("import-other-gl", "gitlab", raw)
	if err != nil || fs[0].Category != "dast" {
		t.Fatalf("natural category: %v %+v", err, fs)
	}
	// DAST request and response details (cookies) are not kept.
	loc, err := LocateImport("import-other-gl", "gl-dast", raw, fs[0].Fingerprint)
	if err != nil {
		t.Fatal(err)
	}
	if strings.Contains(string(loc.Raw), "0123456789abcdef") || !strings.Contains(string(loc.Raw), "present, not kept") {
		t.Errorf("located DAST record: %s", loc.Raw)
	}
	if !strings.Contains(fs[0].Description, "GET https://app.example/search (parameter q)") {
		t.Errorf("description: %q", fs[0].Description)
	}
	fz, _ := ParseImport("import-other-gl", "", readImport(t, "gl-coverage-fuzzing.json"))
	if !strings.Contains(fz[0].Description, "no severity") {
		t.Errorf("unknown severity is explained: %q", fz[0].Description)
	}
	// A likely false positive flag lowers the confidence.
	flagged := `{"version":"15.0.0","vulnerabilities":[{"id":"1","category":"sast","name":"x","severity":"High","identifiers":[{"type":"semgrep_id","name":"r","value":"r"}],
		"location":{"file":"a.py","start_line":1},"flags":[{"type":"flagged-as-likely-false-positive","origin":"vet","description":"test code"}]}],
		"scan":{"type":"sast","scanner":{"id":"semgrep"}}}`
	if DetectImportFormat([]byte(flagged)) != "gl-sast" {
		t.Fatal("detect flagged")
	}
	if g, err := ParseImport("import-sast-x", "", []byte(flagged)); err != nil || g[0].Confidence != "low" || !strings.Contains(g[0].Description, "test code") {
		t.Errorf("flagged: %v %+v", err, g)
	}
	// Report types without an alias use the generic format.
	if got := DetectImportFormat([]byte(`{"version":"15.0.0","vulnerabilities":[],"scan":{"type":"api_fuzzing","scanner":{"id":"x"}}}`)); got != "gitlab" {
		t.Errorf("api fuzzing: %q", got)
	}
}

func TestImportIaCVerdicts(t *testing.T) {
	// tfsec: passed results are not findings, ignored ones are low
	// confidence; terrascan skipped violations likewise.
	tf := `{"results":[{"rule_id":"AVD-1","long_id":"a","severity":"HIGH","status":1,"resource":"r","location":{"filename":"a.tf","start_line":1,"end_line":2}},
		{"rule_id":"AVD-2","long_id":"b","severity":"HIGH","status":2,"resource":"r","location":{"filename":"a.tf","start_line":1,"end_line":2}}]}`
	if g, err := ParseImport("import-iac-x", "", []byte(tf)); err != nil || len(g) != 1 || g[0].RuleID != "AVD-2" || g[0].Confidence != "low" {
		t.Errorf("tfsec: %v %+v", err, g)
	}
	ts := `{"results":{"violations":[],"skipped_violations":[{"rule_id":"AC_1","rule_name":"n","severity":"HIGH","file":"a.tf","line":3,"skip_comment":"accepted"}],"scan_summary":{}}}`
	if g, err := ParseImport("import-iac-x", "", []byte(ts)); err != nil || len(g) != 1 || g[0].Confidence != "low" || !strings.Contains(g[0].Description, "accepted") {
		t.Errorf("terrascan: %v %+v", err, g)
	}
	// Conftest exceptions are imported as low-confidence info.
	ct := `[{"filename":"a.yaml","namespace":"main","successes":0,"exceptions":[{"msg":"excepted","metadata":{"query":"data.main.deny"}}]}]`
	if g, err := ParseImport("import-iac-x", "", []byte(ct)); err != nil || len(g) != 1 || g[0].Severity != "info" || g[0].Confidence != "low" {
		t.Errorf("conftest: %v %+v", err, g)
	}
	// Legitify group-by schemes are detected but rejected with a hint.
	if DetectImportFormat([]byte(`{"type":"group-by-severity","content":{}}`)) != "legitify" {
		t.Error("legitify group-by detection")
	}
	if _, err := ParseImport("import-other-x", "legitify", []byte(`{"type":"group-by-severity","content":{}}`)); err == nil || !strings.Contains(err.Error(), "flattened") {
		t.Errorf("legitify group-by: %v", err)
	}
	// KICS paths: the container prefix is removed, other paths are kept.
	if kicsPath("../../path/infra/main.tf") != "infra/main.tf" || kicsPath("path/x.tf") != "path/x.tf" {
		t.Error("kics path")
	}
	// Scorecard: score 10 and -1 are not findings; 5-9 lowers the risk.
	sc := `{"repo":{"name":"github.com/a/b"},"scorecard":{"version":"v5"},"score":5,"checks":[{"name":"Code-Review","score":10},{"name":"Packaging","score":-1},{"name":"Maintained","score":6,"reason":"r"}]}`
	if g, err := ParseImport("import-other-x", "", []byte(sc)); err != nil || len(g) != 1 || g[0].Severity != "medium" {
		t.Errorf("scorecard: %v %+v", err, g)
	}
}

func TestImportGitLabAndIaCEmptyAndMalformed(t *testing.T) {
	for doc, f := range map[string]string{
		`{"version":"15.0.0","vulnerabilities":[],"scan":{"type":"sast","scanner":{"id":"semgrep"}}}`:              "gl-sast",
		`{"version":"15.0.0","vulnerabilities":[],"scan":{"type":"secret_detection","analyzer":{"id":"secrets"}}}`: "gl-secret-detection",
		`{"version":"15.0.0","vulnerabilities":[],"scan":{"type":"container_scanning","scanner":{"id":"trivy"}}}`:  "gl-container-scanning",
		`{"kics_version":"v2","queries_total":10,"queries":[]}`:                                                    "kics",
		`{"results":null}`: "tfsec",
		`{"results":{"violations":null,"skipped_violations":null,"scan_errors":null,"scan_summary":{}}}`: "terrascan",
		`{"Checks":[],"Reports":[],"Summary":{}}`:                                                        "kube-linter",
		`{"issues":[],"errors":[]}`:                                                                      "tflint",
		`{"PolarisOutputVersion":"1.0","Results":[]}`:                                                    "polaris",
		`{"Controls":[],"Totals":{}}`:                                                                    "kube-bench",
		`{"findings":[],"rules":{},"packages":{}}`:                                                       "poutine",
		`{"type":"flattened","content":{}}`:                                                              "legitify",
		`{"repo":{"name":"x"},"scorecard":{"version":"v5"},"checks":[]}`:                                 "scorecard",
		`{"generationTime":"x","summaryDetails":{},"results":[],"resources":[]}`:                         "kubescape",
	} {
		if got := DetectImportFormat([]byte(doc)); got != f {
			t.Errorf("%s: detected %q, want %q", doc, got, f)
			continue
		}
		if fs, err := ParseImport("import-other-x", f, []byte(doc)); err != nil || len(fs) != 0 {
			t.Errorf("%s: %v %d", f, err, len(fs))
		}
	}
	// Empty arrays of the array formats parse with a named format.
	for _, f := range []string{"cfn-lint", "cfn-nag", "hadolint", "conftest"} {
		if fs, err := ParseImport("import-iac-x", f, []byte(`[]`)); err != nil || len(fs) != 0 {
			t.Errorf("%s: empty: %v", f, err)
		}
	}
	for f, doc := range map[string]string{
		"gl-sast":     `{"version":"15","vulnerabilities":[{"severity":"High"}],"scan":{"type":"sast","scanner":{}}}`,
		"kics":        `{"kics_version":"v2","queries":[{"query_name":"x"}]}`,
		"tfsec":       `{"results":[{"severity":"HIGH"}]}`,
		"terrascan":   `{"results":{"violations":[{"severity":"HIGH"}],"scan_summary":{}}}`,
		"kube-linter": `{"Checks":[],"Reports":[{"Remediation":"x"}],"Summary":{}}`,
		"kubescape":   `{"summaryDetails":{},"results":[{"resourceID":"x","controls":[{"name":"x"}]}],"resources":[]}`,
		"cfn-lint":    `[{"Filename":"a","Level":"Error","Location":{},"Rule":{}}]`,
		"cfn-nag":     `[{"filename":"a","file_results":{"violations":[{"type":"FAIL"}]}}]`,
		"hadolint":    `[{"file":"Dockerfile","level":"error","line":1,"message":"x","column":1,"code":""}]`,
		"tflint":      `{"issues":[{"message":"x","range":{}}],"errors":[]}`,
		"conftest":    `[{"filename":"a","namespace":"main","successes":0,"failures":[{"metadata":{}}]}]`,
		"kube-bench":  `{"Controls":[{"id":"1","tests":[{"section":"1.1","results":[{"status":"FAIL"}]}]}],"Totals":{}}`,
		"poutine":     `{"findings":[{"meta":{}}],"rules":{}}`,
		"legitify":    `{"type":"flattened","content":{"p":{"policyInfo":{},"violations":[{"canonicalLink":"x"}]}}}`,
		"scorecard":   `{"repo":{},"scorecard":{},"checks":[{"reason":"x"}]}`,
	} {
		if _, err := ParseImport("import-other-x", f, []byte(doc)); err == nil {
			t.Errorf("%s: malformed record accepted", f)
		}
	}
}
